with with_last as (select s.id, s.customer_id, s.started_at, s.country, x.duration_sec, x.page from sessions s left join lateral (select c.duration_sec, c.page from web_events c where c.session_id = s.id order by c.duration_sec desc, c.id desc limit 1) x on true) select page, min(started_at) as first_seen, count(distinct country) as distinct_countries, percentile_approx(duration_sec, array(0.25, 0.5, 0.75)) as duration_sec_quartiles, min(duration_sec) as min_duration_sec from with_last group by page order by distinct_countries desc
